import sys

d = sys.stdin.read().split()
n = int(d[0])
p = [int(x) for x in d[1:1 + n]]

def best(r):
    if r == 0:
        return 0
    return max(p[j - 1] + best(r - j) for j in range(1, r + 1))

print(best(n))

