            p = [rng.randint(1, 6) * (i + 1) + rng.randint(0, 3) for i in range(n)]
        tests.append(fmt(p))
    n = 2000
    tests.append(fmt([rng.randint(1, 10 ** 6) for _ in range(n)]))
    tests.append(fmt([10 ** 6] * n))
    tests.append(fmt([(i + 1) * 500 for i in range(n)]))
    tests.append(fmt(sorted(rng.randint(1, 10 ** 6) for _ in range(n))))
    tests.append(fmt([rng.randint(900000, 10 ** 6) // (i % 7 + 1) + i for i in range(n)]))
    return tests

